def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    from collections import deque

    size = len(alphabet)
    char_index = {ch: i for i, ch in enumerate(alphabet)}
    transitions = [[-1] * size]
    failure = [0]
    terminal = [False]

    for word in banned:
        state = 0
        for ch in word:
            index = char_index[ch]
            if transitions[state][index] == -1:
                transitions[state][index] = len(transitions)
                transitions.append([-1] * size)
                failure.append(0)
                terminal.append(False)
            state = transitions[state][index]
        terminal[state] = True

    queue = deque()
    for index in range(size):
        child = transitions[0][index]
        if child == -1:
            transitions[0][index] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        terminal[state] |= terminal[failure[state]]
        for index in range(size):
            child = transitions[state][index]
            if child == -1:
                transitions[state][index] = transitions[failure[state]][index]
            else:
                failure[child] = transitions[failure[state]][index]
                queue.append(child)

    states = [state for state in range(len(transitions)) if not terminal[state]]
    state_index = {state: i for i, state in enumerate(states)}
    count = len(states)

    matrix = [[0] * count for _ in range(count)]
    for state in states:
        source = state_index[state]
        for destination in transitions[state]:
            if not terminal[destination]:
                matrix[source][state_index[destination]] += 1

    vector = [0] * count
    vector[state_index[0]] = 1

    def multiply_vector(vec, mat):
        result = [0] * count
        for i, value in enumerate(vec):
            if value:
                for j, coefficient in enumerate(mat[i]):
                    result[j] += value * coefficient
        return [value % MOD for value in result]

    def square_matrix(mat):
        result = [[0] * count for _ in range(count)]
        for i in range(count):
            for k, value in enumerate(mat[i]):
                if value:
                    for j, coefficient in enumerate(mat[k]):
                        result[i][j] += value * coefficient
            for j in range(count):
                result[i][j] %= MOD
        return result

    while n:
        if n & 1:
            vector = multiply_vector(vector, matrix)
        n >>= 1
        if n:
            matrix = square_matrix(matrix)

    return sum(vector) % MOD
